(555, NULL, 'Joubert', 'Joubert', 'country', 'SACMAF AWARD WINNER 2023\r\nATKV-Crescendo mentorship finalist 2025.\r\nLive entertainment for weddings, birthdays, functions, Pub\'s, Festival\'s etc', '060 717 0457', NULL, NULL, NULL, 'https://www.facebook.com/profile.php?id=100089755264460', NULL, 'artists/profile_pictures/DzgPcP7uITXr18ndOu0GpKblkx6l3AJOFZntPdCc.jpg', NULL, NULL, '2025-10-11 19:51:37', '2025-10-12 14:27:43', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'none', NULL, NULL),
(556, NULL, 'No Friends of Harry', 'No Friends of Harry', 'rock', 'No Friends Of Harry are a South African gothic/alternative rock band from Johannesburg who were active in the 1980s and 1990s. They released three albums on independent South African labels, with a compilation album being released by EMI Records shortly after the band broke up in 1998.', NULL, NULL, NULL, NULL, NULL, NULL, 'artists/profile_pictures/cgXKjfI4S4WfB1DUNc2Jp5ClPyNKiobMVvzJGJzQ.jpg', NULL, NULL, '2025-10-12 17:28:12', '2025-10-12 17:28:30', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'none', NULL, NULL),
(559, NULL, 'Sometimes Useless at Night', 'Sometimes Useless at Night', 'metal', 'Skate Punk, Rock, Slam Metal with some bass and drums and good old guitaring mixed with some of the new. Long time friends on a musical journey', NULL, NULL, NULL, NULL, NULL, NULL, 'artists/profile_pictures/sRUFCdExevUk2G6LUGTlstdrYSPwjT3pe8ukvBke.jpg', NULL, NULL, '2025-10-13 22:14:37', '2025-10-13 23:29:19', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'none', NULL, NULL),
(560, NULL, 'Ashton Nyte', 'Ashton Nyte', 'goth', 'Ashton Nyte is a South African-born musician who is the frontman of the gothic rock band The Awakening.', NULL, NULL, NULL, NULL, NULL, NULL, 'artists/profile_pictures/pjP6XkSy6ZMjTqRPdH2G5BbyoZBCBWMMh0JN4Cy9.jpg', NULL, NULL, '2025-10-14 13:19:51', '2025-10-14 13:30:56', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'none', NULL, NULL),
(561, NULL, 'Brent Harris and Thee Jam', 'Brent Harris', 'indie', 'Brent Harris - drummer and founding member of SA supergroup Just Jinjer - presents the top caliber corporate act Brent Harris and Thee Jam.  This uber-talented and entertaining hit band has become a dominant force in the corporate entertainment market. With a core of top South African musicians including Multi-Instrumentalist Denholm Harding, Mandlenkosi Goodman Buthelezi on Trumpet, Wanda Zonke on Saxophone and Riaan Van Rensburg on Percussion, the band incorporates a variety of exceptionally talented and entertaining vocalists - Rene Mabotha, Dez Peterson, Nigel Morkel and Boki Ntsime. Thee Jam\'s performance includes jazzy background sets, up tempo party sessions, and the unforgettable DRUM SOLO, including various other drummers playing in sync with water and lights.  With one of the largest repertoires in the business, Thee Jam can complement just about any event.', NULL, NULL, NULL, NULL, NULL, NULL, 'artists/profile_pictures/B43Size3ixLjFi0BMK6GXvpjR3gX6NFCjX0fWN7I.jpg', NULL, NULL, '2025-10-14 16:21:38', '2025-10-14 16:22:32', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'none', NULL, NULL),
