INSERT INTO `genres` (`id`, `name`, `slug`, `description`, `is_active`, `created_at`, `updated_at`) VALUES
(2, 'Rock', 'rock', 'Rock music is a broad genre of popular music that originated in the 1950s, characterized by a strong beat, simple chord structure, and often electric guitars.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(3, 'Jazz', 'jazz', 'Jazz is a music genre characterized by swing and blue notes, complex chords, call and response vocals, polyrhythms and improvisation.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(4, 'Hip Hop', 'hip-hop', 'Hip hop music is a genre of popular music that originated in the 1970s, consisting of stylized rhythmic music that commonly accompanies rapping.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(5, 'Electronic', 'electronic', 'Electronic music is music that employs electronic musical instruments, digital instruments, or circuitry-based music technology in its creation.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(6, 'Pop', 'pop', 'Pop music is a genre of popular music that originated in its modern form during the mid-1950s, characterized by catchy melodies and simple chord progressions.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(7, 'R&B', 'rb', 'Rhythm and blues (R&B) is a genre of popular music that originated in African American communities in the 1940s, combining elements of jazz, gospel, and blues.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(8, 'Country', 'country', 'Country music is a genre of popular music that originated in the Southern United States in the 1920s, characterized by simple harmonies and folk lyrics.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(9, 'Reggae', 'reggae', 'Reggae is a music genre that originated in Jamaica in the late 1960s, characterized by a strong backbeat and often socially conscious lyrics.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(10, 'Blues', 'blues', 'Blues is a music genre and musical form that originated in the Deep South of the United States around the 1860s, characterized by blue notes and a twelve-bar structure.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(11, 'Classical', 'classical', 'Classical music generally refers to the formal musical tradition of the Western world, considered to be distinct from Western folk music or popular music traditions.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(12, 'Metal', 'metal', 'Heavy metal is a genre of rock music that developed in the late 1960s and early 1970s, characterized by highly amplified distortion and powerful vocals.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(13, 'Folk', 'folk', 'Folk music is a music genre that includes traditional folk music and the contemporary genre that evolved from the former during the 20th-century folk revival.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(14, 'Soul', 'soul', 'Soul music is a popular music genre that originated in the African American community, combining elements of gospel music and rhythm and blues.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(15, 'Indie', 'indie', 'Indie music is music produced independently from commercial record labels, often characterized by experimental sounds and artistic freedom.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(16, 'Gospel', 'gospel', 'Gospel music is a traditional genre of Christian music, characterized by dominant vocals and strong use of harmony with Christian lyrics.', 1, '2025-10-09 19:54:12', '2025-10-09 19:54:12'),
(18, 'Afrikaans musiek', 'afrikaans-musiek', 'Afrikaans musiek', 1, '2025-10-13 19:33:51', '2025-10-13 19:33:51'),
(19, 'Kwaito', 'kwaito', 'Kwaito', 1, '2025-10-13 19:34:15', '2025-10-13 19:34:15'),
(20, 'Amapiano', 'amapiano', 'A hybrid of kwaito, deep house, gqom, jazz, soul, and lounge music characterized by synths and wide, percussive basslines. The word \"amapiano\" derives from the IsiZulu word for \"pianos\".', 1, '2025-10-13 19:36:04', '2025-10-13 19:36:04'),
(21, 'Live cover musician', 'live-cover-musician', 'Live cover musician', 1, '2025-10-13 19:38:10', '2025-10-13 19:38:10'),
(22, 'Goth', 'goth', 'Goth is a music-based subculture that emerged in the United Kingdom in the early 1980s. The subculture developed around gothic rock, a genre that evolved from British post-punk.', 1, '2025-10-14 13:18:50', '2025-10-14 13:18:50'),
(23, 'Punk', 'punk', 'Punk rock is a subgenre of rock music that emerged in the mid-1970s. Rooted in 1950s rock and roll and 1960s garage rock, punk bands rejected the overproduction and corporate nature of mainstream rock music.', 1, '2025-11-01 12:20:23', '2025-11-01 12:20:23'),
(24, 'Entertainer', 'entertainer', 'This covers other artistic types, like comedians, DJ\'s, quiz masters etc.', 1, '2025-11-01 16:28:37', '2025-11-01 16:28:37'),
(25, 'DJ', 'dj', 'DJ or Presenter/MC', 1, '2025-11-15 12:19:29', '2025-11-15 12:19:29');
